def fill_gaps(g):
    h,w=len(g),len(g[0])
    out=[r[:] for r in g]
    for i in range(h):
        for j in range(w):
            if g[i][j]==0:
                if i>0 and i<h-1 and g[i-1][j]!=0 and g[i-1][j]==g[i+1][j]:
