def T3(g):
    bg=Counter(v for r in g for v in r).most_common(1)[0][0]
    h,w=len(g),len(g[0])
    g=[r[:] for r in g]
    # 1) delete object cells in bottom row
    for j in range(w): g[h-1][j]=bg
    # 2) 4-connected objects
    objs=comps(g,bg)
    # gravity: each rigid object falls until blocked (floor or other object), processed bottom-up
    occ=[[g[i][j]!=bg for j in range(w)] for i in range(h)]
    # sort objects by their lowest cell
    objs.sort(key=lambda c: max(a for a,b in c))
    for cells in objs:
        colmap={}
        for a,b in cells: colmap.setdefault(b,[]).append(a)
        d=0
        while True:
            ok=True
            for b,rows in colmap.items():
                for a in rows:
                    na=a+d+1
                    if na>=h or (na<h and occ[na][b] and (na,b) not in [(x+d2,y) for x,y, d2 in []]):
                        pass
            # simpler: check target cells
            for b,rows in colmap.items():
                for a in rows:
                    na=a+d+1
                    if na>=h: ok=False; break
                    if occ[na][b]:
                        # occupied by another object (this object's own cells tracked separately)
                        ok=False; break
                if not ok: break
            if not ok: break
            d+=1
        # place
        for a,b in cells: occ[a][b]=False
        for a,b in cells:
            occ[a+d][b]=True
        for a,b in cells: g[a][b]=bg
        for a,b in cells: g[a+d][b]=g[a+d][b] if False else (cells[0] and None)
    return g

def grav2(g):
    g=[r[:] for r in g]
    bg=Counter(v for r in g for v in r).most_common(1)[0][0]
    h,w=len(g),len(g[0])
    objs=[]; seen=set()
    for i in range(h):
        for j in range(w):
            if g[i][j]!=bg and (i,j) not in seen:
                st=[(i,j)]; c=[]
                while st:
                    a,b=st.pop()
                    if (a,b) in seen: continue
                    seen.add((a,b)); c.append((a,b,g[a][b]))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+da,b+db
                        if 0<=na<h and 0<=nb<w and g[na][nb]!=bg and (na,nb) not in seen: st.append((na,nb))
                objs.append(c)
    # bottom-up: floor-resting objects sink exactly 1; others fall to rest
    for cells in sorted(objs, key=lambda c: max(a for a,b,v in c)):
        colmax={}
        for a,b,v in cells: colmax[b]=max(colmax.get(b,-1),a)
        touches_floor = any(a==h-1 for a,b,v in cells)
        if touches_floor:
            d=1
        else:
            d=0
            while not any(colmax[b]+d+1>=h or g[colmax[b]+d+1][b]!=bg for b in colmax): d+=1
        for a,b,v in cells: g[a][b]=bg
        for a,b,v in cells:
            na=a+d
            if na<h: g[na][b]=v
    return g

