from collections import Counter

def background(grid):
    """The most common color in the grid."""
    return Counter(v for row in grid for v in row).most_common(1)[0][0]

def shift_down(grid, n=1, fill=None):
    """The grid shifted down n rows; vacated top rows are filled with fill (default: background color); bottom rows are lost."""
    if fill is None:
        fill = background(grid)
    return [[fill]*len(grid[0]) for _ in range(n)] + grid[:-n]

